import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"أسئلة شائعة وحل المشكلات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/faq.md","filePath":"ar/guide/faq.md"}'),s={name:"ar/guide/faq.md"};function n(d,e,c,i,l,p){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="أسئلة-شائعة-وحل-المشكلات" tabindex="-1">أسئلة شائعة وحل المشكلات <a class="header-anchor" href="#أسئلة-شائعة-وحل-المشكلات" aria-label="Permalink to &quot;أسئلة شائعة وحل المشكلات&quot;">​</a></h1><h2 id="الإعداد" tabindex="-1">الإعداد <a class="header-anchor" href="#الإعداد" aria-label="Permalink to &quot;الإعداد&quot;">​</a></h2><p><strong>تعرض لوحة التحكم “setup issues”.</strong> انقر على المؤشر: يعرض كل فحص فاشل طريقة إصلاحه. السبب الأكثر شيوعاً غياب ffmpeg (على Windows: <code>winget install Gyan.FFmpeg</code>، وعلى macOS: <code>brew install ffmpeg</code>، وعلى Linux: مدير الحزم). ثم أعد تشغيل <code>start.bat</code> أو <code>start.sh</code>.</p><p><strong>تظهر الرسالة “Cannot launch Chromium”.</strong> شغّل <code>reelforge doctor --fix</code>. وعلى Linux أعد تشغيل المثبّت أيضاً ووافق على تثبيت مكتبات النظام.</p><p><strong>تظهر الرسالة “ffmpeg not found” رغم تثبيته (Windows).</strong> أغلق كل الطرفيات و<code>start.bat</code> ثم أعد فتحها، فلا يقرأ Windows قيمة PATH الجديدة إلا في النوافذ الجديدة.</p><p>تجد إصلاحات أخرى للإعداد في <a href="./installation.html#troubleshooting">التثبيت</a>.</p><h2 id="الحلقات" tabindex="-1">الحلقات <a class="header-anchor" href="#الحلقات" aria-label="Permalink to &quot;الحلقات&quot;">​</a></h2><p><strong>تفشل الإشارة إلى كلمة: <code>Word &quot;x&quot; not found in line l7</code>.</strong> تعرض رسالة الخطأ أقرب كلمة في ذلك السطر. وتُطابَق الكلمات مع تجاهل علامات الترقيم والتشكيل. وللكلمة التي تحتوي على فاصلة عليا استخدم علامات الاقتباس المزدوجة: <code>l7:&quot;Conway&#39;s&quot;</code>. ويمكنك أيضاً استخدام رقم الكلمة: <code>l7.3</code> (الكلمة الرابعة).</p><p><strong>تمتد الترجمة النصية على ثلاثة أسطر (V-10).</strong> أضف <code>break: [&quot;word&quot;]</code> إلى سطر النص لبدء سطر جديد في الترجمة قبل تلك الكلمة، أو خفّض <code>captions.max_chars</code> في الثيم.</p><p><strong>يتجاوز النص صندوقه (V-9).</strong> اختصر النص، أو خفّض <code>fontSize</code>، أو كبّر <code>place.w/h</code>. وتتقلص العناوين والاقتباسات والأختام تلقائياً لتتسع في صناديقها.</p><p><strong>عنصر يقع تحت أزرار TikTok ‏(V-7).</strong> اضغط <strong>Z</strong> في المحرر لإظهار المناطق الآمنة، وأبعد المحتوى عن المناطق الحمراء. وفي الجزء السفلي من المسرح التزم بـ <code>x + w ≤ 920</code>.</p><p><strong>عنصران متداخلان (V-8).</strong> أعطِ الأول <code>exit</code> قبل دخول الثاني، أو حرّك أحدهما، أو ضع الشارات والأختام على <code>layer: overlay</code>.</p><p><strong>سطر “يُنطق بسرعة كبيرة” (V-14).</strong> فيه أكثر من 3.5 كلمة في الثانية تقريباً. قسّمه إلى سطرين أو اختصره.</p><h2 id="الخطوط-واللغات-والمقاسات" tabindex="-1">الخطوط واللغات والمقاسات <a class="header-anchor" href="#الخطوط-واللغات-والمقاسات" aria-label="Permalink to &quot;الخطوط واللغات والمقاسات&quot;">​</a></h2><p><strong>هل يمكنني استخدام خطوطي الخاصة؟</strong> يمكن للثيمات استخدام أي عائلة مضمّنة (Space Grotesk وInter وManrope وPlayfair Display وJetBrains Mono وCairo وNoto Kufi Arabic وNoto Naskh Arabic وReadex Pro). الخطوط مضمّنة حتى لا تعتمد نتيجة التصدير على الجهاز، والخطوط الأخرى غير مدعومة حالياً.</p><p><strong>ما اللغات المدعومة؟</strong> الترجمة النصية متاحة بالإنجليزية والعربية، بما في ذلك الجمل العربية التي تحتوي على مصطلحات إنجليزية.</p><p><strong>هل يمكنني صنع فيديو مربع أو أفقي؟</strong> ليس في الإصدار 1.0: يصدّر ReelForge فيديو عمودياً بمقاس 9:16 فقط (ADR-016). المقاسات المربعة والطولية والأفقية ضمن خطة التطوير.</p><h2 id="العمل-دون-اتصال-والخوادم-والذكاء-الاصطناعي" tabindex="-1">العمل دون اتصال والخوادم والذكاء الاصطناعي <a class="header-anchor" href="#العمل-دون-اتصال-والخوادم-والذكاء-الاصطناعي" aria-label="Permalink to &quot;العمل دون اتصال والخوادم والذكاء الاصطناعي&quot;">​</a></h2><p><strong>هل يحتاج ReelForge إلى الإنترنت؟</strong> فقط أثناء التثبيت (الاعتماديات وChromium وffmpeg) ولتنزيل نماذج الكلام الاختيارية مرة واحدة. أما الإنشاء والتحرير والتصدير فتعمل دون اتصال تماماً. وإن استخدمت مساعد ذكاء اصطناعي، فالمساعد نفسه يحتاج إلى اتصاله وحسابه الخاص، بينما يبقى خادم MCP الخاص بـ ReelForge محلياً.</p><p><strong>هل يمكنني التصدير على خادم أو في CI؟</strong> نعم: كل شيء متاح من سطر الأوامر (يعطي <code>--json</code> مخرجات قابلة للقراءة الآلية)، ويعمل دون واجهة رسومية على Linux.</p><p><strong>هل يرسل ReelForge ملفاتي إلى أي مكان؟</strong> لا. ترتبط الخوادم افتراضياً بالعنوان <code>127.0.0.1</code>، ويحجب محرك الرسم الوصول إلى الشبكة. ولا يرى عميل الذكاء الاصطناعي إلا ما يقرؤه عبر الأدوات.</p><h2 id="الحقوق-والملفات" tabindex="-1">الحقوق والملفات <a class="header-anchor" href="#الحقوق-والملفات" aria-label="Permalink to &quot;الحقوق والملفات&quot;">​</a></h2><p><strong>هل يمكنني بيع الفيديوهات التي أصنعها؟</strong> نعم. الفيديوهات ملكك، بما في ذلك للعملاء والقنوات الربحية. راجع <a href="./license.html">الترخيص</a>.</p><p><strong>أين ملفاتي؟</strong> كل حلقة مجلد في <code>episodes/</code> يحتوي على <code>episode.yaml</code> و<code>voice.wav</code> و<code>cues.json</code> و<code>assets/</code> و<code>out/</code>. انسخه احتياطياً كأي مجلد آخر (وGit خيار جيد لذلك).</p><h2 id="الحصول-على-المساعدة" tabindex="-1">الحصول على المساعدة <a class="header-anchor" href="#الحصول-على-المساعدة" aria-label="Permalink to &quot;الحصول على المساعدة&quot;">​</a></h2><p>اسأل في <a href="https://github.com/TerminalDZ/vidcreat/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a> أو افتح <a href="https://github.com/TerminalDZ/vidcreat/issues" target="_blank" rel="noreferrer">بلاغاً (issue)</a>. أرفق نظام التشغيل، ومخرجات الأمر <code>reelforge doctor --json</code>، والأمر الذي شغّلته مع <code>--verbose</code>.</p>',26)])])}const u=o(s,[["render",n]]);export{h as __pageData,u as default};
